use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input = input.as_array().unwrap();
    let mut frequency: HashMap<String, i64> = HashMap::new();
    for item in input {
        let str_item = item.as_str().unwrap();
        *frequency.entry(str_item.to_string()).or_insert(0) += 1;
    }
    Value::Object(frequency.into_iter().map(|(k, v)| (k, Value::Number(serde_json::Number::from(v as i64))).collect())
}
